package dev.veltraph.client.core;
import java.util.function.Supplier;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class DirectStoredLifecycleCurrentTest {
 @Test void repeatedReadsCheckActualPrivateFieldsWithoutRoleCallbacks(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);var captured=root.lifecycleSnapshot();actor.roleThrows=true;for(int i=0;i<100;i++)assertTrue(root.lifecycleCurrent(captured));assertEquals(0,actor.roleReads);}
 @Test void actualEnableDisableABARevokesOldStoredSnapshot(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);var old=root.lifecycleSnapshot();actor.setEnabled(false);actor.setEnabled(true);assertTrue(actor.isEnabled());assertFalse(root.lifecycleCurrent(old));assertTrue(root.lifecycleCurrent(root.lifecycleSnapshot()));}
 @Test void actualStateAndRegistrationMutationsAreStillDetected(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);var old=root.lifecycleSnapshot();actor.pause();assertFalse(root.lifecycleCurrent(old));var paused=root.lifecycleSnapshot();assertTrue(root.lifecycleCurrent(paused));root.register(new Actor("second"));assertFalse(root.lifecycleCurrent(paused));}
 @Test void supplierBindingABAIsNotCached(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);Supplier<Module> a=()->actor;root.leasedInputOwner(a);var old=root.lifecycleSnapshot();root.leasedInputOwner(()->null);root.leasedInputOwner(a);assertFalse(root.lifecycleCurrent(old));assertTrue(root.lifecycleCurrent(root.lifecycleSnapshot()));}
 @Test void callbackForeignEnableIsSeenAfterCallback(){var root=new ModuleManager();var actor=new Actor("parent");var foreign=new Actor("foreign");root.register(actor);root.register(foreign);actor.setEnabled(true);var captured=root.lifecycleSnapshot();Supplier<Module> callback=()->{foreign.setEnabled(true);return actor;};assertSame(actor,callback.get());assertFalse(root.lifecycleCurrent(captured));}
 @Test void differentRegistryAndNullRemainUnavailable(){var a=new ModuleManager();var b=new ModuleManager();a.register(new Actor("parent"));b.register(new Actor("parent"));assertFalse(b.lifecycleCurrent(a.lifecycleSnapshot()));assertFalse(a.lifecycleCurrent(null));}
 @Test void unknownModuleImplementationRemainsUnavailableWithoutVirtualReads(){var root=new ModuleManager();var unknown=new Unknown();root.register(unknown);int ids=unknown.idReads;var captured=root.lifecycleSnapshot();assertFalse(captured.known());assertFalse(root.lifecycleCurrent(captured));assertEquals(ids,unknown.idReads);}
 static final class Unknown implements Module {int idReads;public String id(){idReads++;return "unknown";}public String displayName(){throw new AssertionError();}public ModuleCategory category(){return ModuleCategory.INTERMEDIARY;}public boolean isEnabled(){throw new AssertionError();}public void setEnabled(boolean value){throw new AssertionError();}public void onEnable(){}public void onDisable(){}public void onTick(){}public MacroState state(){throw new AssertionError();}}
 static final class Actor extends AbstractModule {boolean roleThrows;int roleReads;Actor(String id){super(id,id,ModuleCategory.INTERMEDIARY);}void pause(){setState(MacroState.PAUSED);}@Override public boolean ownsGameplayInput(){roleReads++;if(roleThrows)throw new IllegalStateException("must not query role");return true;}}
}
